const customersData = rawData.map((item, index) => {
    const parts = item.ma_tuyen.split(' - ');
    return {
        id: index + 1,
        name: `${item.npp} - ${parts[0]}`,
        npp: item.npp,
        ma_tuyen: item.ma_tuyen,
        nhan_vien: parts[0],
        lat: parseFloat(item.vi_do),
        lng: parseFloat(item.kinh_do)
    };
});

// Bảng màu sặc sỡ, dễ phân biệt
const colorPalette = [
    '#FF1744', // Đỏ đậm
    '#00E5FF', // Xanh dương neon
    '#76FF03', // Xanh lá neon
    '#FF9100', // Cam đậm
    '#E040FB', // Tím neon
    '#FFEA00', // Vàng chanh
    '#00BFA5', // Xanh ngọc
    '#FF4081', // Hồng đậm
    '#18FFFF', // Xanh lơ
    '#FF6E40', // Cam nhạt
    '#7C4DFF', // Tím
    '#69F0AE', // Xanh mint
    '#FFAB40', // Vàng cam
    '#F50057', // Hồng neon
    '#00E676', // Xanh lá
    '#D500F9', // Tím đậm
    '#FFD740', // Vàng
    '#304FFE', // Xanh dương đậm
    '#FF3D00', // Cam đỏ
    '#1DE9B6', // Xanh ngọc nhạt
    '#C51162', // Hồng đậm
    '#00B0FF', // Xanh trời
    '#FFC400', // Vàng đậm
    '#651FFF', // Tím đậm
    '#00E5FF'  // Xanh dương nhạt
];

// Hàm tạo màu sắc động cho nhân viên trong từng NPP
function getEmployeeColor(npp, employee) {
    const key = `${npp}_${employee}`;
    
    // Tạo hash từ key để chọn màu nhất quán
    let hash = 0;
    for (let i = 0; i < key.length; i++) {
        hash = ((hash << 5) - hash) + key.charCodeAt(i);
        hash = hash & hash;
    }
    const colorIndex = Math.abs(hash) % colorPalette.length;
    
    return colorPalette[colorIndex];
}

// Hàm lấy danh sách nhân viên theo NPP
function getEmployeesByNPP(npp) {
    if (npp === 'all') {
        return [...new Set(customersData.map(c => c.nhan_vien))].sort();
    }
    return [...new Set(customersData.filter(c => c.npp === npp).map(c => c.nhan_vien))].sort();
}

// Hàm thống kê theo NPP
function getStatsByRegion() {
    const stats = {};
    customersData.forEach(customer => {
        if (!stats[customer.npp]) {
            stats[customer.npp] = { count: 0, customers: [] };
        }
        stats[customer.npp].count++;
        stats[customer.npp].customers.push(customer);
    });
    return stats;
}

// Hàm lọc theo NPP
function filterCustomersByRegion(npp) {
    if (npp === 'all') return customersData;
    return customersData.filter(customer => customer.npp === npp);
}

// Hàm lọc theo danh sách nhân viên
function filterCustomersByEmployees(employees) {
    if (!employees || employees.length === 0) return customersData;
    return customersData.filter(customer => employees.includes(customer.nhan_vien));
}

// Hàm lọc kết hợp NPP và danh sách nhân viên
function filterCustomersByBoth(npp, selectedEmployees) {
    let result = customersData;
    if (npp !== 'all' && npp !== '') {
        result = result.filter(customer => customer.npp === npp);
    }
    if (selectedEmployees && selectedEmployees.length > 0) {
        result = result.filter(customer => selectedEmployees.includes(customer.nhan_vien));
    }
    return result;
}

